const actors:NativeActor[]=[],unsupported:string[]=[];
const models=new Set<string>();
if(!layoutConfiguration.layouts[String(lines.length)])unsupported.push(`原生布局 Chara${lines.length} 没有已提取的原版动画，暂不能预览`);
for(const [lineIndex,line] of lines.entries()){
  // SetLive2D selects CharaN using the raw LF-split count, but skips empty
  // entries without incrementing its one-based PosN creation counter.
  // Keep both indices before any drawing-order sort so layout assignment
  // cannot move when a later entry has a lower SortingGroup order.
  if(line==="")continue;
  const parts=line.split(/\s*:\s*/);
  const model=modelName(parts[0]);
  const sort_order=parts.length>=2?sorting(parts[1]):0;
  const position=parts.length>=3?vector(parts[2]):zero();
  const angle=parts.length>=4?vector(parts[3]):zero();
  let scale=parts.length>=5?vector(parts[4]):one();
  // SetTransform (0x128a928–978) replaces an explicitly zero scale with
  // Vector3.one. The values are parent transforms, independent of the
  // extracted CH_top prefab layout; they do not replace that inner layout.
  if(scale.x===0&&scale.y===0&&scale.z===0)scale=one();
  if(models.has(model))unsupported.push("同一人物模型的重复实例暂未接入预览");
  models.add(model);
  if(angle.x!==0||angle.y!==0)unsupported.push("人物包含暂未接入预览的三维旋转");
  if(position.z!==0)unsupported.push("人物包含尚未验证的原生深度位移，暂不能按静态画面预览");
  const order=drawingOrder(model,sort_order),layout=nativeLayout(lines.length,actors.length+1);
  if(order.effective_sort_order===null)unsupported.push(`人物 ${model} 的原版预设绘制顺序尚未提取`);
  if(!layout.slot)unsupported.push(`原生布局 ${layout.clip} 的 ${layout.slot_index} 号位置尚未提取`);
  actors.push({model,...motion,extra_motions:[...motion.extra_motions],speaking:false,
    placement:{space:"native_parent",position,angle,scale,sort_order,...order,opacity:opacity(parts[5]),
      source:{entry:originalLines[lineIndex],line_index:lineIndex+1,entry_index:actors.length+1,entry_count:lines.length},
      layout,projection:{...layoutConfiguration.projection}}});
}
// Higher native SortingGroup orders draw in front. Unresolved defaults
// block playback and keep source order rather than inventing an order.
// Equal resolved orders remain in original creation order; the source and
// slot records above survive this back-to-front compositor arrangement.
if(actors.every(actor=>actor.placement.effective_sort_order!==null))actors.sort((left,right)=>
  left.placement.effective_sort_order!-right.placement.effective_sort_order!
    ||left.placement.source.entry_index-right.placement.source.entry_index);
return {model:"",actors,unsupported:[...new Set(unsupported)]};

fitNativeParent(){
  const parent=this.placement,actor=this.assets.actors[this.detail.id],slot=parent.layout?.slot;
  if(!actor)throw new Error('没有找到该模型的原版位置参数：'+this.detail.id);
  if(!slot)throw new Error('此人物的原生人数布局位置尚未提取');
  const projection=parent.projection,width=this.stage.clientWidth,height=this.stage.clientHeight;
  if(projection?.mode!=='neutral_9_16_zero_depth')throw new Error('此人物的原生投影方式尚未验证');
  // The verified reduction is a neutral 9:16 card. clientWidth/Height are
  // integer CSS pixels, so permit only their subpixel-rounding discrepancy,
  // not an unverified screen-aspect correction. Other native screen ratios
  // need CardScaler and Canvas/UV presentation to be composed together.
  if(!(width>0&&height>0)||Math.abs(width-height*projection.aspect_width/projection.aspect_height)>1)
    throw new Error('原生多角色静态预览需要 9:16 画面');
  if(parent.angle.x!==0||parent.angle.y!==0||slot.angle.x!==0||slot.angle.y!==0)
    throw new Error('人物的三维旋转尚未接入预览');
  if(parent.position.z!==0||actor.position.z!==0||slot.position.z!==0)
    throw new Error('此人物的原生深度尚未验证，不能按静态画面预览');
  if(slot.scale.x!==slot.scale.y)throw new Error('此原生人数布局的非均匀缩放尚未验证');
  // APK 1.19.7 SetLive2D attaches each created entry under the original
  // CharaN/PosN slot, then Live2D.Util.SetTransform applies script-local
  // vectors to the model root; CH_top remains inside that root. Apply
  // slot * script * CH_top, preserving each source transform separately.
  // CardScaleCharaPosition divides its ancestor by G=MaskWidth/1920 on a
  // neutral 9:16 card. The full-UV 1920-square render target is displayed
  // into that same MaskWidth, cancelling G for zero-depth actor geometry.
  // The existing direct-canvas projection already represents that result;
  // adding an isolated G or 1/G here would change the solo baseline.
  const scriptOrigin=transformedPoint(actor.position,parent);
  const world=transformedPoint(scriptOrigin,slot);
  const camera=this.assets.space.camera;
  const origin=this.assets.space.transforms[this.playerConfig.native_camera].m_LocalPosition;
  const distance=world.z-origin.z;
  if(!(distance>0))throw new Error('原生人物位于当前预览相机后方');
  const pixels=this.stage.clientHeight/(2*distance*Math.tan(camera['field of view']*Math.PI/360));
  const internal=this.model.internalModel,info=this.core.getModel().canvasinfo;
  this.model.scale.set(actor.scale.x*parent.scale.x*slot.scale.x*pixels/info.PixelsPerUnit/internal.localTransform.a,
    actor.scale.y*parent.scale.y*slot.scale.y*pixels/info.PixelsPerUnit/internal.localTransform.d);
  this.model.anchor.set(.5,.5);
  // Unity's positive Z angle is counterclockwise in its upward-Y plane;
  // the browser's downward-Y canvas therefore uses the opposite sign.
  this.model.rotation=-(parent.angle.z+slot.angle.z)*Math.PI/180;
  this.model.position.set(this.stage.clientWidth/2+(world.x-origin.x)*pixels,
    this.stage.clientHeight/2-(world.y-origin.y)*pixels);
  this.model.alpha=parent.opacity;
  console.info('STORY_NATIVE_ACTOR_PROJECTION',JSON.stringify({model:this.detail.id,node:document.body.dataset.node,at:performance.now(),
    source:parent.source,script:{position:parent.position,angle:parent.angle,scale:parent.scale,sort_order:parent.sort_order},
    layout:parent.layout,projection,sort_order:parent.effective_sort_order,sort_source:parent.sort_source,
    // Keep model-canvas geometry separate from script/layout transforms.
    // A per-model vertical discrepancy cannot be assigned to an authored
    // offset or pose until canvas origin and PIXI conversion are observed.
    world,pixels,ppu:info.PixelsPerUnit,viewport:[width,height],
    canvas:{width:info.CanvasWidth,height:info.CanvasHeight,originX:info.CanvasOriginX,originY:info.CanvasOriginY},
    internalTransform:{a:internal.localTransform.a,b:internal.localTransform.b,c:internal.localTransform.c,
      d:internal.localTransform.d,tx:internal.localTransform.tx,ty:internal.localTransform.ty},
    anchor:{x:this.model.anchor.x,y:this.model.anchor.y},
    projectedPosition:{x:this.model.x,y:this.model.y},modelScale:{x:this.model.scale.x,y:this.model.scale.y}}));

  if(actor.detail?.id!==row.model||!this.present?.has(row.model)){
    if(!await actor.load(await readJSON('/api/model/'+encodeURIComponent(row.model))))return false;
    actor.model.visible=false;
  }
  if(generation!==this.generation)return false;
  actor.placement=row.placement;actor.fit();
  const prior=this.states.get(row.model),resolved=structuredClone(row);
  const changed=!!(row.body||row.face||row.extra_motions.length);
  resolved.face_reset=changed||!!prior?.face_reset;
  if(!row.body&&prior)resolved.body=prior.body;
  if(!changed&&prior)resolved.face=prior.face;
  const states=this.primary.motionIndex.models[row.model].states;
  const semantics=this.primary.motionSemantics;
  const layers=new Set(row.extra_motions.flatMap(token=>extraLayers(states,token,semantics)));
  resolved.extra_motions=[...(prior?.extra_motions||[]).filter(token=>!extraLayers(states,token,semantics).some(layer=>layers.has(layer))),...row.extra_motions];
  const held=['body','face'].filter(kind=>!row[kind]&&resolved[kind])
    .map(kind=>({layer:semantics.motion_layers[kind],token:heldState(actor.detail,resolved[kind])}));
  for(const token of resolved.extra_motions.filter(token=>!row.extra_motions.includes(token)))
    for(const layer of extraLayers(states,token,semantics))held.push({layer,token:heldState(actor.detail,token)});
  await actor.applyStoryMotion({body:motionState(actor.detail,row.body),face:motionState(actor.detail,row.face),
    extra:row.extra_motions,held,
    clearLayers:resolved.face_reset&&!resolved.face?[semantics.motion_layers.face]:[],
    command:[row.body,row.face,...row.extra_motions].filter(Boolean).join(','),allowStill:true});
  await actor.lighting.apply(context);
  if(generation!==this.generation)return false;
  next.set(row.model,resolved);prepared.push(actor);
}
this.rows=rows;this.states=next;this.present=new Set(rows.map(row=>row.model));
// Reorder existing children after every resource has completed. This keeps
// partial loads from revealing an incorrect overlap or an incomplete cast.
for(const actor of prepared)this.primary.app.stage.setChildIndex(actor.model,this.primary.app.stage.children.length-1);
this.preparing=false;this.visible(true);
console.info('STORY_CAST_DISPLAY',JSON.stringify(rows.map(row=>({model:row.model,placement:row.placement,speaking:row.speaking}))));

this.core = model.internalModel.coreModel;
const native = this.core.getModel();
this.parameters = native.parameters.defaultValues.slice();
this.parts = native.parts.opacities.slice();
this.baseWidth = model.width;
this.baseHeight = model.height;
// Group composition owns the reveal. Set visibility before attaching
// the model: animation and lighting preparation continue asynchronously
// after this method returns, while PIXI can render between those awaits.
model.visible = this.visibleOnLoad;
this.app.stage.addChild(model);
model.internalModel.on('beforeModelUpdate', () => this.renderPose());
this.fit();
this.ready = true;
installed = true;
console.info('MODEL_READY', detail.id, native.parameters.count, this.baseWidth, this.baseHeight, 'visible='+model.visible);

render(){
  this.clock();
  const native=this.viewer.core.getModel();native.parameters.values.set(this.viewer.parameters);
  native.parts.opacities.set(this.viewer.parts);this.viewer.model.alpha=1;
  for(const layer of this.definition.layers){
    if(layer===this.choiceLayer)this.renderChoice();
    const row=this.layers.get(layer.name);if(!row)continue;
    const fade=row.fade?Math.min(1,(this.time-row.fade.start)/row.fade.duration):1;
    for(const item of this.statePose(row))this.apply(item.curve,item.value,row.weight*fade);
  }
}
